<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import GuestLayout from'../../Layouts/GuestLayout.vue';const form=useForm({login:'',password:'',remember:false})</script>
<template><GuestLayout><Head title="ورود"/><h1 class="mb-5 text-xl font-bold">ورود به سامانه</h1><form class="space-y-4" @submit.prevent="form.post('/login')"><div><label for="login">ایمیل یا شماره موبایل</label><input id="login" v-model="form.login" autocomplete="username" autofocus required :aria-invalid="!!form.errors.login" aria-describedby="login-error"><p id="login-error" v-if="form.errors.login" class="mt-1 text-sm text-red-600">{{form.errors.login}}</p></div><div><label for="password">رمز عبور</label><input id="password" v-model="form.password" type="password" autocomplete="current-password" required :aria-invalid="!!form.errors.password" aria-describedby="password-error"><p id="password-error" v-if="form.errors.password" class="mt-1 text-sm text-red-600">{{form.errors.password}}</p></div><label class="flex items-center gap-2"><input v-model="form.remember" type="checkbox" class="h-4 w-4"> مرا به خاطر بسپار</label><button :disabled="form.processing" class="w-full rounded-xl bg-teal-700 px-4 py-2.5 font-bold text-white disabled:opacity-50">{{form.processing?'در حال ورود…':'ورود'}}</button><Link href="/forgot-password" class="block text-center text-sm text-teal-700">رمز عبور را فراموش کرده‌اید؟</Link></form></GuestLayout></template>
